# ---- 手刻：牛頓法，無正則化 ----
def sigmoid(z):
    return 1.0 / (1.0 + np.exp(-np.clip(z, -500, 500)))

w = np.zeros(Xb_train.shape[1])
for it in range(50):
    p = sigmoid(Xb_train @ w)
    grad = Xb_train.T @ (p - y_train)          # n_loglik 的梯度
    H = Xb_train.T @ (Xb_train * (p * (1 - p))[:, None])  # Hessian
    step = np.linalg.solve(H + 1e-10 * np.eye(len(w)), grad)
    w -= step
    if np.linalg.norm(step) < 1e-10:
        break
